const PR54=[{label:"Ví dụ: Thuật toán Kahn",input:"6 7\n5 1\n5 3\n1 2\n3 2\n2 4\n6 4\n3 6\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    vector<int> vao(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        vao[v]++;\n    }\n    queue<int> q;\n    for (int u = 1; u <= n; u++) if (vao[u] == 0) q.push(u);\n    vector<int> thuTu;\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        thuTu.push_back(u);\n        for (int v : adj[u]) {\n            vao[v]--;                  // gỡ cạnh u -> v\n            if (vao[v] == 0) q.push(v);\n        }\n    }\n    for (int x : thuTu) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,adj:"adj",base:1,n:"n",lab:"vao",cur:["u","v"]},{type:"cont",of:"q"},{type:"cells",of:"thuTu"}],py:{code:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nvao = [0] * (n + 1)\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    vao[v] += 1\nq = deque(u for u in range(1, n + 1) if vao[u] == 0)\nthu_tu = []\nwhile q:\n    u = q.popleft()\n    thu_tu.append(u)\n    for v in adj[u]:\n        vao[v] -= 1                    # gỡ cạnh u -> v\n        if vao[v] == 0:\n            q.append(v)\nprint(*thu_tu)",viz:[{type:"graph",dir:true,adj:"adj",base:1,n:"n",lab:"vao",cur:["u","v"]},{type:"cont",of:"q"},{type:"cells",of:"thu_tu"}]},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\nusing System.Linq;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        int[] vao = new int[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            vao[e[1]]++;\n        }\n        var q = new Queue<int>();\n        for (int u = 1; u <= n; u++) if (vao[u] == 0) q.Enqueue(u);\n        var thuTu = new List<int>();\n        while (q.Count > 0)\n        {\n            int u = q.Dequeue();\n            thuTu.Add(u);\n            foreach (int v in adj[u])\n            {\n                vao[v]--;                      // gỡ cạnh u -> v\n                if (vao[v] == 0) q.Enqueue(v);\n            }\n        }\n        Console.WriteLine(string.Join(\" \", thuTu));\n    }\n}"}},{label:"Ví dụ: Thứ tự tô pô bằng DFS",input:"6 7\n5 1\n5 3\n1 2\n3 2\n2 4\n6 4\n3 6\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\n\nvector<vector<int>> adj;\nvector<bool> tham;\nvector<int> xong;\n\nvoid dfs(int u) {\n    tham[u] = true;\n    for (int v : adj[u])\n        if (!tham[v]) dfs(v);\n    xong.push_back(u);                 // u kết thúc sau mọi đỉnh đi tới được từ u\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    adj.resize(n + 1);\n    tham.assign(n + 1, false);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n    }\n    for (int u = 1; u <= n; u++) if (!tham[u]) dfs(u);\n    reverse(xong.begin(), xong.end());\n    for (int x : xong) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,adj:"adj",base:1,n:"n",mark:"tham",cur:["u"]},{type:"cells",of:"xong"},{type:"calls"}],py:{code:"n, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\ntham = [False] * (n + 1)\nxong = []\n\ndef dfs(u):\n    tham[u] = True\n    for v in adj[u]:\n        if not tham[v]:\n            dfs(v)\n    xong.append(u)                     # u kết thúc sau mọi đỉnh đi tới được từ u\n\nfor u in range(1, n + 1):\n    if not tham[u]:\n        dfs(u)\nxong.reverse()\nprint(*xong)"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\nusing System.Linq;\n\nclass Program\n{\n    static List<int>[] adj;\n    static bool[] tham;\n    static List<int> xong = new List<int>();\n\n    static void Dfs(int u)\n    {\n        tham[u] = true;\n        foreach (int v in adj[u])\n            if (!tham[v]) Dfs(v);\n        xong.Add(u);                       // u kết thúc sau mọi đỉnh đi tới được từ u\n    }\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        tham = new bool[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n        }\n        for (int u = 1; u <= n; u++) if (!tham[u]) Dfs(u);\n        xong.Reverse();\n        Console.WriteLine(string.Join(\" \", xong));\n    }\n}"}},{label:"Ví dụ: Nhỏ nhất theo thứ tự từ điển",input:"5 3\n3 1\n4 1\n2 5\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    vector<int> vao(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        vao[v]++;\n    }\n    priority_queue<int, vector<int>, greater<int>> pq;   // luôn lấy đỉnh nhỏ nhất sẵn sàng\n    for (int u = 1; u <= n; u++) if (vao[u] == 0) pq.push(u);\n    while (!pq.empty()) {\n        int u = pq.top();\n        pq.pop();\n        cout << u << \" \";\n        for (int v : adj[u])\n            if (--vao[v] == 0) pq.push(v);\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,adj:"adj",base:1,n:"n",lab:"vao",cur:["u"]},{type:"cont",of:"pq"}],py:{code:"import heapq\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nvao = [0] * (n + 1)\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    vao[v] += 1\npq = [u for u in range(1, n + 1) if vao[u] == 0]   # luôn lấy đỉnh nhỏ nhất sẵn sàng\nheapq.heapify(pq)\nout = []\nwhile pq:\n    u = heapq.heappop(pq)\n    out.append(u)\n    for v in adj[u]:\n        vao[v] -= 1\n        if vao[v] == 0:\n            heapq.heappush(pq, v)\nprint(*out)",viz:[{type:"graph",dir:true,adj:"adj",base:1,n:"n",lab:"vao",cur:["u"]},{type:"cont",of:"pq",as:"priority_queue"}]},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\nusing System.Linq;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        int[] vao = new int[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            vao[e[1]]++;\n        }\n        var pq = new PriorityQueue<int, int>();   // luôn lấy đỉnh nhỏ nhất sẵn sàng\n        for (int u = 1; u <= n; u++) if (vao[u] == 0) pq.Enqueue(u, u);\n        var sb = new StringBuilder();\n        while (pq.Count > 0)\n        {\n            int u = pq.Dequeue();\n            sb.Append(u).Append(' ');\n            foreach (int v in adj[u])\n                if (--vao[v] == 0) pq.Enqueue(v, v);\n        }\n        Console.WriteLine(sb.ToString());\n    }\n}"}},{label:"Ví dụ: Đường đi dài nhất trên DAG",input:"6 7\n5 1\n5 3\n1 2\n3 2\n2 4\n6 4\n3 6\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    vector<int> vao(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        vao[v]++;\n    }\n    int t[7] = {0, 3, 2, 4, 1, 2, 5};  // thời gian làm việc 1..6\n    vector<int> f(n + 1, 0);           // f[v]: thời điểm sớm nhất làm xong v\n    queue<int> q;\n    for (int u = 1; u <= n; u++) if (vao[u] == 0) { q.push(u); f[u] = t[u]; }\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : adj[u]) {\n            f[v] = max(f[v], f[u] + t[v]);      // v chỉ bắt đầu khi u xong\n            if (--vao[v] == 0) q.push(v);\n        }\n    }\n    cout << *max_element(f.begin(), f.end()) << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,adj:"adj",base:1,n:"n",lab:"f",cur:["u","v"]}],py:{code:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nvao = [0] * (n + 1)\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    vao[v] += 1\nt = [0, 3, 2, 4, 1, 2, 5]              # thời gian làm việc 1..6\nf = [0] * (n + 1)                      # f[v]: thời điểm sớm nhất làm xong v\nq = deque()\nfor u in range(1, n + 1):\n    if vao[u] == 0:\n        q.append(u)\n        f[u] = t[u]\nwhile q:\n    u = q.popleft()\n    for v in adj[u]:\n        f[v] = max(f[v], f[u] + t[v])  # v chỉ bắt đầu khi u xong\n        vao[v] -= 1\n        if vao[v] == 0:\n            q.append(v)\nprint(max(f))"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\nusing System.Linq;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        int[] vao = new int[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            vao[e[1]]++;\n        }\n        int[] t = { 0, 3, 2, 4, 1, 2, 5 };     // thời gian làm việc 1..6\n        int[] f = new int[n + 1];              // f[v]: thời điểm sớm nhất làm xong v\n        var q = new Queue<int>();\n        for (int u = 1; u <= n; u++) if (vao[u] == 0) { q.Enqueue(u); f[u] = t[u]; }\n        while (q.Count > 0)\n        {\n            int u = q.Dequeue();\n            foreach (int v in adj[u])\n            {\n                f[v] = Math.Max(f[v], f[u] + t[v]);   // v chỉ bắt đầu khi u xong\n                if (--vao[v] == 0) q.Enqueue(v);\n            }\n        }\n        Console.WriteLine(f.Max());\n    }\n}"}},{label:"Lỗi: đồ thị có chu trình",input:"5 5\n1 2\n2 3\n3 4\n4 2\n4 5\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    vector<int> vao(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        vao[v]++;\n    }\n    queue<int> q;\n    for (int u = 1; u <= n; u++) if (vao[u] == 0) q.push(u);\n    int daXep = 0;\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        daXep++;\n        for (int v : adj[u])\n            if (--vao[v] == 0) q.push(v);\n    }\n    if (daXep < n) cout << \"co chu trinh, chi xep duoc \" << daXep << \" dinh\\n\";\n    else cout << \"xep duoc\\n\";\n    return 0;\n}",viz:[{type:"graph",dir:true,adj:"adj",base:1,n:"n",lab:"vao",cur:["u"]}],py:{code:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nvao = [0] * (n + 1)\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    vao[v] += 1\nq = deque(u for u in range(1, n + 1) if vao[u] == 0)\nda_xep = 0\nwhile q:\n    u = q.popleft()\n    da_xep += 1\n    for v in adj[u]:\n        vao[v] -= 1\n        if vao[v] == 0:\n            q.append(v)\nif da_xep < n:\n    print(\"co chu trinh, chi xep duoc\", da_xep, \"dinh\")\nelse:\n    print(\"xep duoc\")"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\nusing System.Linq;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        int[] vao = new int[n + 1];\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            vao[e[1]]++;\n        }\n        var q = new Queue<int>();\n        for (int u = 1; u <= n; u++) if (vao[u] == 0) q.Enqueue(u);\n        int daXep = 0;\n        while (q.Count > 0)\n        {\n            int u = q.Dequeue();\n            daXep++;\n            foreach (int v in adj[u])\n                if (--vao[v] == 0) q.Enqueue(v);\n        }\n        if (daXep < n) Console.WriteLine(\"co chu trinh, chi xep duoc \" + daXep + \" dinh\");\n        else Console.WriteLine(\"xep duoc\");\n    }\n}"}}];
